{"doneWhen":{"all":[{"path":"countObjects(kind=item, name=Crown)","op":">=","value":1}]},"modes":[{"id":"collect-and-craft","priority":10,"when":{"all":[{"path":"body.x","op":">=","value":0}]},"macro":"skill","params":{"name":"field-work"}}],"skills":[{"name":"field-work","skill":"async (b) => {
  const need = { Wood: 3, Stone: 2 };
  const have = { Wood: 0, Stone: 0 };
  const inv = await b.items();
  for (const it of inv) {
    if (it.name === 'Wood') have.Wood += it.stack;
    if (it.name === 'Stone') have.Stone += it.stack;
  }
  b.log('start have ' + JSON.stringify(have));

  const pick = async (name, x, y) => {
    if (have[name] >= need[name]) return true;
    const r = await b.walkTo(x, y, 'adjacent');
    if (!r.ok) { b.log('walk fail ' + name + ' ' + r.reason); return false; }
    const p = await b.faceAndPress(x, y, 'KeyE');
    b.log('pick ' + name + ' ' + JSON.stringify(p));
    if (p && p.ok) have[name] += 1;
    return true;
  };

  // Wood is reachable directly (no door).
  await pick('Wood', 10, 3);
  await pick('Wood', 10, 1);

  // Stone is behind the blue door; need the blue key first.
  if (have.Stone < need.Stone) {
    const k = await b.walkTo(11, 1, 'adjacent');
    if (k.ok) {
      const kp = await b.faceAndPress(11, 1, 'KeyE');
      b.log('blue key ' + JSON.stringify(kp));
    } else {
      b.log('blue key walk fail ' + k.reason);
    }
    const d = await b.walkTo(8, 6, 'adjacent');
    if (d.ok) {
      const dp = await b.faceAndPress(8, 6, 'KeyE');
      b.log('blue door ' + JSON.stringify(dp));
    } else {
      b.log('blue door walk fail ' + d.reason);
    }
    await pick('Stone', 10, 7);
    await pick('Stone', 11, 8);
  }

  if (have.Wood < 3 || have.Stone < 2) {
    b.log('missing materials ' + JSON.stringify(have));
    return;
  }
  const w = await b.walkTo(6, 2, 'adjacent');
  if (!w.ok) { b.log('bench walk fail ' + w.reason); return; }
  const c = await b.faceAndPress(6, 2, 'KeyC');
  b.log('craft ' + JSON.stringify(c));
}","check":"async (b) => {
